import { useState, useEffect } from 'react';

const IMG_GARBAGE = "data:image/png;base64,";
const IMG_PPE = "data:image/png;base64,";

const SlidePlantMonitoring = () => {
  const [currentScene, setCurrentScene] = useState(0);
  const [showAlert, setShowAlert] = useState(false);
  const [fadeState, setFadeState] = useState('visible');

  const scenes = [
    {
      id: 1,
      image: IMG_GARBAGE,
      title: "Garbage Detection",
      camera: "CAM-12",
      location: "Zone C • Street 4",
      time: "2:30 PM",
      alert: "Waste Accumulation Detected",
      alertType: "cleanliness",
      details: ["Multiple garbage bags detected", "Detection line crossed", "Area requires cleanup"],
      notifyTo: ["Sanitation Head", "Zone Supervisor"],
      severity: "medium"
    },
    {
      id: 2,
      image: IMG_PPE,
      title: "PPE Compliance Monitoring",
      camera: "CAM-08",
      location: "Construction Site • Block A",
      time: "10:15 AM",
      alert: "PPE Violation Detected",
      alertType: "safety",
      details: ["1 worker without helmet", "Safety vest: Compliant", "Immediate action required"],
      notifyTo: ["Safety Officer", "Site Manager"],
      severity: "high"
    }
  ];

  useEffect(() => {
    const sceneInterval = setInterval(() => {
      setFadeState('fading');
      setTimeout(() => {
        setCurrentScene((prev) => (prev + 1) % scenes.length);
        setShowAlert(false);
        setFadeState('visible');
      }, 500);
    }, 6000);

    return () => clearInterval(sceneInterval);
  }, []);

  useEffect(() => {
    const alertTimer = setTimeout(() => {
      setShowAlert(true);
    }, 1500);
    return () => clearTimeout(alertTimer);
  }, [currentScene]);

  const scene = scenes[currentScene];

  const getSeverityColor = (severity) => {
    switch(severity) {
      case 'high': return { bg: '#dc2626', text: '#fff' };
      case 'medium': return { bg: '#f59e0b', text: '#1a1a1a' };
      default: return { bg: '#22c55e', text: '#fff' };
    }
  };

  const getAlertIcon = (type) => {
    switch(type) {
      case 'security': return '🛡️';
      case 'cleanliness': return '🗑️';
      case 'safety': return '⛑️';
      default: return '⚠️';
    }
  };

  const useCases = [
    { icon: "🦺", title: "PPE Compliance", desc: "Hard hat, vest & glove detection" },
    { icon: "⚠️", title: "Safety Zone Violation", desc: "Restricted area breach alerts" },
    { icon: "📋", title: "Maintenance Validation", desc: "Checklist completion tracking" },
    { icon: "🚫", title: "Unauthorized Access", desc: "Identity & badge verification" },
    { icon: "📊", title: "Shift Productivity", desc: "Real-time efficiency metrics" },
  ];

  return (
    <div style={{
      height: '100vh',
      background: 'linear-gradient(180deg, #f0f1f3 0%, #e4e5e7 100%)',
      fontFamily: '"IBM Plex Sans", system-ui, sans-serif',
      padding: '20px 20px 16px',
      display: 'flex',
      flexDirection: 'column' as const,
      overflow: 'hidden',
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500&display=swap');
        
        @keyframes slideInRight {
          from { transform: translateX(100%); opacity: 0; }
          to { transform: translateX(0); opacity: 1; }
        }
        
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        
        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.5; }
        }
        
        @keyframes scanline {
          0% { top: 0; }
          100% { top: 100%; }
        }
        
        @keyframes blink {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.3; }
        }
      `}</style>

      {/* Header */}
      <div style={{
        maxWidth: '960px',
        margin: '0 auto 12px',
        textAlign: 'center',
      }}>
        <h2 className="slide-title" style={{ marginBottom: 6 }}>Real-Time <em>Activity Monitoring</em></h2>
        <p style={{
          fontSize: '13px',
          color: 'hsl(var(--slide-muted))',
          margin: 0,
        }}>Compliance Validation in Operations</p>
      </div>

      {/* Main Display */}
      <div style={{
        maxWidth: '960px',
        margin: '0 auto 16px',
        flex: '1',
        minHeight: 0,
        background: '#1a1d21',
        borderRadius: '8px',
        border: '1px solid #333',
        boxShadow: '0 8px 32px rgba(0,0,0,0.2)',
        overflow: 'hidden',
      }}>
        {/* Top Bar */}
        <div style={{
          background: 'linear-gradient(180deg, #2a2d32 0%, #1f2227 100%)',
          padding: '12px 16px',
          borderBottom: '1px solid #333',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
            <div style={{ display: 'flex', gap: '6px' }}>
              <div style={{ width: '10px', height: '10px', borderRadius: '50%', background: '#ef4444' }} />
              <div style={{ width: '10px', height: '10px', borderRadius: '50%', background: '#facc15' }} />
              <div style={{ width: '10px', height: '10px', borderRadius: '50%', background: '#22c55e' }} />
            </div>
            <span style={{
              fontFamily: '"IBM Plex Mono", monospace',
              fontSize: '12px',
              color: '#9ca3af',
            }}>{scene.camera} • {scene.location} • LIVE</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <span style={{
              fontFamily: '"IBM Plex Mono", monospace',
              fontSize: '11px',
              color: '#ef4444',
              animation: 'blink 1s infinite',
            }}>● REC</span>
            <span style={{
              fontFamily: '"IBM Plex Mono", monospace',
              fontSize: '11px',
              color: showAlert ? getSeverityColor(scene.severity).bg : '#22c55e',
              fontWeight: '500',
            }}>{showAlert ? '⚠ ALERT' : '● MONITORING'}</span>
          </div>
        </div>

        {/* Video Feed Area */}
        <div style={{
          position: 'relative',
          height: '420px',
          background: '#000',
          overflow: 'hidden',
        }}>
          {/* Main Image */}
          <img 
            src={scene.image} 
            alt={scene.title}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              opacity: fadeState === 'fading' ? 0 : 1,
              transition: 'opacity 0.5s ease-in-out',
            }}
          />

          {/* Scan Line Effect */}
          <div style={{
            position: 'absolute',
            left: 0,
            right: 0,
            height: '2px',
            background: 'linear-gradient(90deg, transparent, rgba(34, 197, 94, 0.4), transparent)',
            animation: 'scanline 4s linear infinite',
            pointerEvents: 'none',
          }} />

          {/* Scene Title Overlay */}
          <div style={{
            position: 'absolute',
            top: '16px',
            left: '16px',
            background: 'rgba(0,0,0,0.75)',
            padding: '10px 16px',
            borderRadius: '4px',
            backdropFilter: 'blur(4px)',
            animation: fadeState === 'visible' ? 'fadeIn 0.5s ease-out' : 'none',
          }}>
            <div style={{
              fontFamily: '"IBM Plex Mono", monospace',
              fontSize: '10px',
              color: '#9ca3af',
              marginBottom: '4px',
            }}>USE CASE {scene.id}/2</div>
            <div style={{
              fontSize: '14px',
              fontWeight: '600',
              color: '#fff',
            }}>{scene.title}</div>
          </div>

          {/* Time Stamp */}
          <div style={{
            position: 'absolute',
            top: '16px',
            right: '16px',
            background: 'rgba(0,0,0,0.75)',
            padding: '8px 12px',
            borderRadius: '4px',
            fontFamily: '"IBM Plex Mono", monospace',
            fontSize: '12px',
            color: '#fff',
          }}>
            {scene.time}
          </div>

          {/* Alert Panel */}
          {showAlert && (
            <div style={{
              position: 'absolute',
              bottom: '16px',
              right: '16px',
              width: '280px',
              background: 'rgba(255,255,255,0.98)',
              borderRadius: '8px',
              boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
              animation: 'slideInRight 0.5s ease-out',
              overflow: 'hidden',
            }}>
              {/* Alert Header */}
              <div style={{
                background: getSeverityColor(scene.severity).bg,
                padding: '12px 14px',
                display: 'flex',
                alignItems: 'center',
                gap: '10px',
              }}>
                <span style={{ fontSize: '18px' }}>{getAlertIcon(scene.alertType)}</span>
                <div>
                  <div style={{
                    fontFamily: '"IBM Plex Mono", monospace',
                    fontSize: '9px',
                    color: getSeverityColor(scene.severity).text,
                    opacity: 0.8,
                    letterSpacing: '0.05em',
                  }}>ALERT TRIGGERED</div>
                  <div style={{
                    fontSize: '12px',
                    fontWeight: '600',
                    color: getSeverityColor(scene.severity).text,
                  }}>{scene.alert}</div>
                </div>
              </div>

              {/* Alert Details */}
              <div style={{ padding: '14px' }}>
                <div style={{
                  fontSize: '11px',
                  color: '#6b7280',
                  marginBottom: '10px',
                }}>
                  {scene.details.map((detail, i) => (
                    <div key={i} style={{ marginBottom: '4px' }}>• {detail}</div>
                  ))}
                </div>

                {/* Notification Recipients */}
                <div style={{
                  background: '#f3f4f6',
                  padding: '10px 12px',
                  borderRadius: '4px',
                  marginBottom: '10px',
                }}>
                  <div style={{
                    fontSize: '10px',
                    fontWeight: '600',
                    color: '#374151',
                    marginBottom: '6px',
                  }}>NOTIFICATION SENT TO:</div>
                  {scene.notifyTo.map((person, i) => (
                    <div key={i} style={{
                      fontSize: '11px',
                      color: '#4b5563',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '6px',
                      marginBottom: '2px',
                    }}>
                      <span style={{ color: '#22c55e' }}>✓</span> {person}
                    </div>
                  ))}
                </div>

                {/* Action Status */}
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                  padding: '8px 10px',
                  background: scene.severity === 'high' ? '#fef2f2' : '#fffbeb',
                  borderRadius: '4px',
                  border: `1px solid ${scene.severity === 'high' ? '#fecaca' : '#fde68a'}`,
                }}>
                  <div style={{
                    width: '6px',
                    height: '6px',
                    borderRadius: '50%',
                    background: scene.severity === 'high' ? '#dc2626' : '#f59e0b',
                    animation: 'pulse 1s infinite',
                  }} />
                  <span style={{
                    fontFamily: '"IBM Plex Mono", monospace',
                    fontSize: '10px',
                    color: scene.severity === 'high' ? '#991b1b' : '#92400e',
                    fontWeight: '500',
                  }}>Awaiting Response</span>
                </div>
              </div>
            </div>
          )}

          {/* Scene Progress Indicator */}
          <div style={{
            position: 'absolute',
            bottom: '16px',
            left: '16px',
            display: 'flex',
            gap: '8px',
          }}>
            {scenes.map((_, i) => (
              <div key={i} style={{
                width: i === currentScene ? '32px' : '10px',
                height: '10px',
                borderRadius: '5px',
                background: i === currentScene ? '#22c55e' : 'rgba(255,255,255,0.4)',
                transition: 'all 0.3s',
                boxShadow: i === currentScene ? '0 0 8px #22c55e' : 'none',
              }} />
            ))}
          </div>
        </div>

        {/* Bottom Stats Bar */}
        <div style={{
          background: 'linear-gradient(180deg, #1f2227 0%, #2a2d32 100%)',
          padding: '12px 20px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          borderTop: '1px solid #333',
        }}>
          <div style={{ display: 'flex', gap: '24px' }}>
            {[
              { label: 'Detection Accuracy', value: '98.7%' },
              { label: 'Response Time', value: '1.2s' },
              { label: 'Active Cameras', value: '24/24' },
            ].map((stat, i) => (
              <div key={i}>
                <div style={{
                  fontFamily: '"IBM Plex Mono", monospace',
                  fontSize: '9px',
                  color: '#6b7280',
                  marginBottom: '2px',
                }}>{stat.label}</div>
                <div style={{
                  fontFamily: '"IBM Plex Mono", monospace',
                  fontSize: '14px',
                  color: '#22c55e',
                  fontWeight: '600',
                }}>{stat.value}</div>
              </div>
            ))}
          </div>
          <div style={{
            fontFamily: '"IBM Plex Mono", monospace',
            fontSize: '10px',
            color: '#6b7280',
          }}>
            AI Engine v2.4.1 • GPU Accelerated
          </div>
        </div>
      </div>

      {/* Use Cases Section */}
      <div style={{ maxWidth: '960px', margin: '0 auto', flexShrink: 0 }}>
        <h2 style={{
          fontSize: '13px',
          fontWeight: '600',
          color: '#6b7280',
          textTransform: 'uppercase',
          letterSpacing: '0.1em',
          marginBottom: '16px',
        }}>More Use Cases</h2>
        
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(5, 1fr)',
          gap: '12px',
        }}>
          {useCases.map((uc, i) => (
            <div key={i} style={{
              background: '#fff',
              border: '1px solid #e5e7eb',
              borderRadius: '4px',
              padding: '16px 12px',
              transition: 'all 0.2s',
              cursor: 'default',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.borderColor = '#b0b0b0';
              e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.08)';
              e.currentTarget.style.transform = 'translateY(-2px)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.borderColor = '#e5e7eb';
              e.currentTarget.style.boxShadow = 'none';
              e.currentTarget.style.transform = 'translateY(0)';
            }}
            >
              <div style={{ fontSize: '22px', marginBottom: '10px' }}>{uc.icon}</div>
              <div style={{
                fontSize: '12px',
                fontWeight: '600',
                color: '#1f2937',
                marginBottom: '4px',
              }}>{uc.title}</div>
              <div style={{
                fontSize: '10px',
                color: '#9ca3af',
                lineHeight: 1.4,
              }}>{uc.desc}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default SlidePlantMonitoring;
